SELECT 'gongkao', '三集合标准型', 'kp-xingce-quantity-math-operation-inclusion-exclusion-three-std', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "三集合标准型"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "总数 = A+B+C - (AB+AC+BC) + ABC + 都不满足。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "涉及三个属性交叉。题目明确给出了“同时满足A和B”、“同时满足A和C”、“同时满足B和C”的具体人数。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "为什么公式长这样？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "把 A、B、C 加起来，其中交集部分（AB、AC、BC）被加了 2 次，最核心的公共部分（ABC）被加了 3 次。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "减去 AB、AC、BC 后，两两交集部分恢复为 1 次。但是，最核心的 ABC 先被加了 3 次，又被减了 3 次，变成了 0 次！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "所以，必须在最后把最核心的 ABC 补加回来 1 次。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[提取三个大圆的数值: A, B, C] --> B[提取三个两两交集的数值: AB, AC, BC]\nB --> C[提取三者皆有的核心数值: ABC]\nC --> D[提取都不满足的数值]\nD --> E[一股脑扔进公式: A+B+C - (AB+AC+BC) + ABC + 都不 = 总数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 100人。A(50)，B(40)，C(30)。AB(15)，AC(10)，BC(12)。ABC(5)。求都不满足几人？"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "代入公式：100 = 50 + 40 + 30 - (15 + 10 + 12) + 5 + 都不。100 = 120 - 37 + 5 + 都不。都不 = 12人。秒杀。"}]}]}$$ AS jsonb), NULL, '三集合标准型的核心考点与实战推导。', category_node.id, CAST('["数量关系", "容斥问题", "三集合标准型"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_quantity_math_operation_inclusion_exclusion_three_std", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
